FUNCTION UNDER TEST:
Name: kohonen_update_weights
Signature: double kohonen_update_weights(const double *X, struct kohonen_array_3d *W, double **D, int num_out, int num_features, double alpha, int R)
Description: /**
 * @brief Update Kohonen network weights for a single input sample.
 *
 * Processes one input vector through the Kohonen Self-Organizing Map (SOM).
 * Finds the Best Matching Unit (BMU) and updates weights within its neighborhood
 * using a Gaussian decay function. The update strength decreases with distance from the BMU.
 *
 * @param X Input feature vector for the current sample. Must not be NULL.
 * @param W 3D weight matrix of the SOM (dimensions: num_out x num_out x num_features).
 *          Weights are modified in-place within the neighborhood of the BMU.
 * @param D Pre-allocated 2D distance matrix (num_out x num_out) used for temporary storage.
 *          Contents are overwritten during computation.
 * @param num_out Number of output nodes along one dimension (grid is num_out x num_out).
 * @param num_features Number of features in the input vector (dimension of weight vectors).
 * @param alpha Current learning rate. Must be positive.
 * @param R Current neighborhood radius. Defines the square region around the BMU for updates.
 *
 * @return The Euclidean distance from the input sample to the Best Matching Unit (BMU).
 *
 * @note This function uses OpenMP pragmas for parallel loops if compiled with OpenMP support.
 * @note The weight update uses a Gaussian kernel: scale_factor = exp(-d²/(2α²)).
 * @see get_min_2d, kohonen_data_3d
 */
Dependencies: get_min_2d, kohonen_data_3d

FUNCTION IMPLEMENTATION (REFERENCE ONLY - do NOT copy into test):
```c
// C program for the function called kohonen_update_weights
// Contains target function implementation and dependency signatures

#include <math.h>
#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <omp.h>

struct kohonen_array_3d
{
    int dim1;     /**< lengths of first dimension */
    int dim2;     /**< lengths of second dimension */
    int dim3;     /**< lengths of thirddimension */
    double *data; /**< pointer to data */
};

// Forward declarations for dependency functions
void get_min_2d(double **X, int N, double *val, int *x_idx, int *y_idx);
double *kohonen_data_3d(const struct kohonen_array_3d *arr, int x, int y, int z);

// Target function implementation
double kohonen_update_weights(const double *X, struct kohonen_array_3d *W,
                              double **D, int num_out, int num_features,
                              double alpha, int R)
{
    int x, y, k;
    double d_min = 0.f;

#ifdef _OPENMP
#pragma omp for
#endif
    // step 1: for each 2D output point
    for (x = 0; x < num_out; x++)
    {
        for (y = 0; y < num_out; y++)
        {
            D[x][y] = 0.f;
            // compute Euclidian distance of each output
            // point from the current sample
            for (k = 0; k < num_features; k++)
            {
                double *w = kohonen_data_3d(W, x, y, k);
                D[x][y] += (w[0] - X[k]) * (w[0] - X[k]);
            }
            D[x][y] = sqrt(D[x][y]);
        }
    }

    // step 2:  get closest node i.e., node with smallest Euclidian distance to
    // the current pattern
    int d_min_x, d_min_y;
    get_min_2d(D, num_out, &d_min, &d_min_x, &d_min_y);

    // step 3a: get the neighborhood range
    int from_x = max(0, d_min_x - R);
    int to_x = min(num_out, d_min_x + R + 1);
    int from_y = max(0, d_min_y - R);
    int to_y = min(num_out, d_min_y + R + 1);

    // step 3b: update the weights of nodes in the
    // neighborhood
#ifdef _OPENMP
#pragma omp for
#endif
    for (x = from_x; x < to_x; x++)
    {
        for (y = from_y; y < to_y; y++)
        {
            /* you can enable the following normalization if needed.
               personally, I found it detrimental to convergence */
            // const double s2pi = sqrt(2.f * M_PI);
            // double normalize = 1.f / (alpha * s2pi);

            /* apply scaling inversely proportional to distance from the
               current node */
            double d2 =
                (d_min_x - x) * (d_min_x - x) + (d_min_y - y) * (d_min_y - y);
            double scale_factor = exp(-d2 / (2.f * alpha * alpha));

            for (k = 0; k < num_features; k++)
            {
                double *w = kohonen_data_3d(W, x, y, k);
                // update weights of nodes in the neighborhood
                w[0] += alpha * scale_factor * (X[k] - w[0]);
            }
        }
    }
    return d_min;
}

